const reticleHud=drawHud;drawHud=()=>{reticleHud();let labels=padActive&&padDevice?[padProfile.buttons.attack===7?'ZR':'Btn '+padProfile.buttons.attack,padProfile.buttons.skill1===2?'Y':'Btn '+padProfile.buttons.skill1,padProfile.buttons.skill2===3?'X':'Btn '+padProfile.buttons.skill2,tutorialButton('dash'),padProfile.buttons.flask===5?'R':'Btn '+padProfile.buttons.flask]:['SHIFT + 左クリック','Q / 右クリック','E','SPACE','1'];document.querySelectorAll('.actions button kbd').forEach((el,i)=>{if(labels[i])hudText(el,labels[i])});};
function drawControllerReticle(){if(started&&!dead&&padActive&&padDevice&&!paused){ctx.save();ctx.strokeStyle='#e2d29b';ctx.lineWidth=1.5;ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(mouse.x,mouse.y,9,0,Math.PI*2);ctx.moveTo(mouse.x-15,mouse.y);ctx.lineTo(mouse.x-6,mouse.y);ctx.moveTo(mouse.x+6,mouse.y);ctx.lineTo(mouse.x+15,mouse.y);ctx.moveTo(mouse.x,mouse.y-15);ctx.lineTo(mouse.x,mouse.y-6);ctx.moveTo(mouse.x,mouse.y+6);ctx.lineTo(mouse.x,mouse.y+15);ctx.stroke();ctx.restore()}};
const avWelcome=welcome;welcome=()=>{avWelcome();$('card').innerHTML=$('card').innerHTML.replace('PC・キーボードとマウス向け / 自動保存','PC・キーボード／ゲームパッド対応 / 自動保存');$('card').insertAdjacentHTML('beforeend','<div class="welcome-options"><button onclick="showControllerSettings()">音・プロコンの設定</button><p class="muted">音は画面を一度クリックして有効化。プロコンはPCに接続後、ボタンを押してください。</p></div>')};if(!started)welcome();
